import sys
import math

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    q = data[0]
    queries = data[1:]

    max_root = math.isqrt(max(queries))
    omega = [0] * (max_root + 1)

    for p in range(2, max_root + 1):
        if omega[p] == 0:
            for multiple in range(p, max_root + 1, p):
                omega[multiple] += 1

    best = [0] * (max_root + 1)
    current = 0
    for i in range(1, max_root + 1):
        if omega[i] == 2:
            current = i
        best[i] = current

    answers = []
    for a in queries:
        root = math.isqrt(a)
        n = best[root]
        answers.append(str(n * n))

    sys.stdout.write("\n".join(answers))

if __name__ == "__main__":
    solve()

import sys


def solve_case(n, k, cakes):
    m = 2 * k

    order = sorted(range(n), key=lambda i: max(cakes[i]), reverse=True)
    selected = order[:m]
    unselected = order[m:]

    base_color = []
    base_value = []
    base_parity = 0
    base_sum = 0

    for i in selected:
        vals = cakes[i]
        c = max(range(3), key=lambda t: vals[t])
        base_color.append(c)
        base_value.append(vals[c])
        base_sum += vals[c]
        base_parity ^= 1 << c

    # Each useful move changes the parity of exactly two colors.
    masks = (3, 5, 6)
    moves = {mask: [] for mask in masks}

    # Recoloring a selected cake.
    for pos, i in enumerate(selected):
        bc = base_color[pos]
        bv = base_value[pos]
        vals = cakes[i]
        for c in range(3):
            if c == bc:
                continue
            mask = (1 << bc) ^ (1 << c)
            moves[mask].append((bv - vals[c], i, -1))

    # Top three unselected cakes for each coordinate.
    best_unselected = []
    for c in range(3):
        arr = sorted(unselected, key=lambda i: cakes[i][c], reverse=True)
        best_unselected.append(arr[:3])

    # Replacing one selected cake by one unselected cake.
    for pos, i in enumerate(selected):
        bc = base_color[pos]
        bv = base_value[pos]
        for c in range(3):
            mask = (1 << bc) ^ (1 << c)
            if mask == 0:
                continue
            for j in best_unselected[c]:
                moves[mask].append((bv - cakes[j][c], i, j))

    # The target parity correction is the current parity.
    target = base_parity

    if target == 0:
        return base_sum

    best_loss = 10**30

    # One move.
    for cost, _, _ in moves[target]:
        if cost < best_loss:
            best_loss = cost

    # Prepare a compact structure for querying the cheapest move
    # avoiding a specified selected and unselected cake.
    prepared = {}
    for mask in masks:
        groups = {}
        for cost, i, j in moves[mask]:
            groups.setdefault(j, []).append((cost, i))

        group_list = []
        for j, arr in groups.items():
            arr.sort()
            # For a fixed j and mask, only the selected cake can conflict.
            # Keeping two distinct selected cakes is sufficient.
            picked = []
            used_i = set()
            for item in arr:
                if item[1] not in used_i:
                    picked.append(item)
                    used_i.add(item[1])
                    if len(picked) == 2:
                        break
            group_list.append((picked[0][0], j, picked))

        group_list.sort()
        prepared[mask] = group_list

    def query(mask, forbidden_i, forbidden_j):
        for _, j, arr in prepared[mask]:
            if j == forbidden_j:
                continue
            for cost, i in arr:
                if i != forbidden_i:
                    return cost
        return 10**30

    # Two moves.
    for a in masks:
        b = a ^ target
        if b not in moves:
            continue
        for cost, i, j in moves[a]:
            other = query(b, i, j)
            total = cost + other
            if total < best_loss:
                best_loss = total

    return base_sum - best_loss


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    t = next(it)
    answers = []

    for _ in range(t):
        n = next(it)
        k = next(it)
        cakes = [(next(it), next(it), next(it)) for _ in range(n)]
        answers.append(str(solve_case(n, k, cakes)))

    sys.stdout.write("\n".join(answers))


