import sys

def solve():
    input = sys.stdin.readline

    n = int(input())
    s = input().strip()
    t = input().strip()

    mapping = [-1] * 26
    used = [False] * 26

    for a, b in zip(s, t):
        x = ord(a) - ord('a')
        y = ord(b) - ord('a')
        used[x] = True
        if mapping[x] == -1:
            mapping[x] = y
        elif mapping[x] != y:
            print(-1)
            return

    edges = 0
    for i in range(26):
        if used[i] and mapping[i] != i:
            edges += 1

    state = [0] * 26
    cycles = 0

    def dfs(u):
        nonlocal cycles
        state[u] = 1
        v = mapping[u]
        if v != u and used[v]:
            if state[v] == 0:
                dfs(v)
            elif state[v] == 1:
                cycles += 1
        state[u] = 2

    for i in range(26):
        if used[i] and state[i] == 0:
            dfs(i)

    if cycles:
        free_letter_exists = len(set(s)) < 26 or len(set(t)) < 26
        if not free_letter_exists:
            print(-1)
            return

    print(edges + cycles)

if __name__ == "__main__":
    solve()

