def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    idx = 1
    answers = []

    for _ in range(t):
        n = data[idx]
        idx += 1
        a = data[idx:idx + n]
        idx += n

        runs = []
        for x in a:
            if not runs or runs[-1] != x:
                runs.append(x)

        stack = []
        reductions = 0

        for x in runs:
            stack.append(x)

            while len(stack) >= 4:
                if stack[-4] == stack[-2] and stack[-3] == stack[-1]:
                    stack.pop()
                    stack.pop()
                    reductions += 1
                else:
                    break

        answers.append(str(len(runs) - reductions))

    sys.stdout.write("\n".join(answers))

