def solve():
    input = sys.stdin.readline

    N, R, C = map(int, input().split())
    S = input().strip()

    row = 0
    col = 0
    seen = {(0, 0)}
    answer = []

    for ch in S:
        if ch == 'N':
            row -= 1
        elif ch == 'S':
            row += 1
        elif ch == 'W':
            col -= 1
        else:  # E
            col += 1

        seen.add((row, col))

        if (row - R, col - C) in seen:
            answer.append('1')
        else:
            answer.append('0')

    print(''.join(answer))

