def solve():
    input = sys.stdin.readline
    n, m = map(int, input().split())

    graph = [[] for _ in range(n)]
    for _ in range(m):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        graph[u].append(v)
        graph[v].append(u)

    color = [-1] * n
    total_color_zero = 0
    has_odd_component = False

    for start in range(n):
        if color[start] != -1:
            continue

        color[start] = 0
        queue = deque([start])
        size = 0

        while queue:
            v = queue.popleft()
            size += 1
            if color[v] == 0:
                total_color_zero += 1

            for to in graph[v]:
                if color[to] == -1:
                    color[to] = color[v] ^ 1
                    queue.append(to)

        if size % 2 == 1:
            has_odd_component = True

    if n % 2 == 1:
        print("Aoki" if m % 2 == 1 else "Takahashi")
    elif has_odd_component:
        print("Aoki")
    else:
        possible_edges_parity = (total_color_zero * (n - total_color_zero)) % 2
        print("Aoki" if (possible_edges_parity - m) % 2 == 1 else "Takahashi")

