import heapq


class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)

        if n - 1 < k:
            return [0] * n

        children = [{}]
        count = [0]
        depth = [0]
        paths = []

        for word in words:
            node = 0
            count[0] += 1
            path = []

            for ch in word:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    count.append(0)
                    depth.append(depth[node] + 1)

                node = nxt
                count[node] += 1
                path.append(node)

            paths.append(path)

        max_depth = max(depth) if depth else 0
        fragile_count = [0] * (max_depth + 1)
        always_valid = 0

        for node in range(1, len(count)):
            if count[node] == k:
                fragile_count[depth[node]] += 1
            elif count[node] >= k + 1:
                always_valid = max(always_valid, depth[node])

        heap = []
        for d in range(max_depth + 1):
            if fragile_count[d] > 0:
                heapq.heappush(heap, -d)

        answer = []

        for path in paths:
            removed_depths = []

            for node in path:
                if count[node] == k:
                    d = depth[node]
                    fragile_count[d] -= 1
                    removed_depths.append(d)

            while heap and fragile_count[-heap[0]] == 0:
                heapq.heappop(heap)

            best_fragile = -heap[0] if heap else 0
            answer.append(max(always_valid, best_fragile))

            for d in removed_depths:
                if fragile_count[d] == 0:
                    heapq.heappush(heap, -d)
                fragile_count[d] += 1

        return answer

