def main():
    N = int(sys.stdin.readline())

    lo, hi = 0, 10**6 + 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if mid * mid * mid <= N:
            lo = mid
        else:
            hi = mid

    for d in range(1, lo + 1):
        if N % d != 0:
            continue

        q = N // d
        discriminant = 12 * q - 3 * d * d
        if discriminant < 0:
            continue

        s = math.isqrt(discriminant)
        if s * s != discriminant:
            continue

        numerator = s - 3 * d
        if numerator <= 0 or numerator % 6 != 0:
            continue

        y = numerator // 6
        x = y + d

        if y > 0 and x * x * x - y * y * y == N:
            print(x, y)
            return

    print(-1)

