from collections import deque


class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        fwd = [to, cap, None]
        rev = [fr, 0, fwd]
        fwd[2] = rev
        self.g[fr].append(fwd)
        self.g[to].append(rev)

    def max_flow(self, s, t):
        flow = 0
        INF = 10**30

        while True:
            level = [-1] * self.n
            level[s] = 0
            q = deque([s])
            while q:
                v = q.popleft()
                for to, cap, rev in self.g[v]:
                    if cap > 0 and level[to] < 0:
                        level[to] = level[v] + 1
                        q.append(to)

            if level[t] < 0:
                return flow

            it = [0] * self.n

            def dfs(v, pushed):
                if v == t:
                    return pushed
                while it[v] < len(self.g[v]):
                    e = self.g[v][it[v]]
                    to, cap, rev = e
                    if cap > 0 and level[to] == level[v] + 1:
                        tr = dfs(to, min(pushed, cap))
                        if tr:
                            e[1] -= tr
                            rev[1] += tr
                            return tr
                    it[v] += 1
                return 0

            while True:
                pushed = dfs(s, INF)
                if not pushed:
                    break
                flow += pushed


def minimum_selected(n, edges, d):
    BIG = 10**9
    layers = n * d
    source = layers
    sink = layers + 1
    dinic = Dinic(layers + 2)

    def node(v, level):
        return v * d + (level - 1)

    # x[v][i] = 1 iff the label of v is at least i.
    # Enforce x[v][i] >= x[v][i+1].
    for v in range(n):
        for i in range(1, d):
            dinic.add_edge(node(v, i + 1), node(v, i), BIG)

    # Source vertex has label 0; target vertex has label d.
    for i in range(1, d + 1):
        dinic.add_edge(node(0, i), sink, BIG)
        dinic.add_edge(source, node(n - 1, i), BIG)

    unary = [0] * layers

    def cost(a, b):
        if b > a + 1:
            return BIG
        return 1 if b == a + 1 else 0

    # Expand each edge cost g(a,b) into threshold variables.
    for u, v in edges:
        u -= 1
        v -= 1

        # Unary terms for the second endpoint.
        for j in range(1, d + 1):
            unary[node(v, j)] += cost(0, j) - cost(0, j - 1)

        # Pair terms and the corresponding unary corrections.
        for i in range(1, d + 1):
            for j in range(1, d + 1):
                c = (
                    cost(i, j)
                    - cost(i - 1, j)
                    - cost(i, j - 1)
                    + cost(i - 1, j - 1)
                )
                if c < 0:
                    cap = -c
                    dinic.add_edge(node(u, i), node(v, j), cap)
                    unary[node(u, i)] -= cap

    offset = 0
    for v, h in enumerate(unary):
        if h >= 0:
            dinic.add_edge(v, sink, h)
        else:
            dinic.add_edge(source, v, -h)
            offset += -h

    cut = dinic.max_flow(source, sink)
    return cut - offset


def main():
    input = sys.stdin.readline
    n, m, k = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(m)]

    answer = 0
    for d in range(1, n):
        needed = minimum_selected(n, edges, d)
        if needed <= k:
            answer = d
        else:
            break

    print(answer)


if __name__ == "__main__":
    main()

import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, K = data[0], data[1]
    V = N * K

    graph = [[] for _ in range(V)]
    idx = 2
    for _ in range(V - 1):
        u = data[idx] - 1
        v = data[idx + 1] - 1
        idx += 2
        graph[u].append(v)
        graph[v].append(u)

    parent = [-2] * V
    parent[0] = -1
    order = [0]

    for v in order:
        for to in graph[v]:
            if to != parent[v]:
                parent[to] = v
                order.append(to)

    rem = [0] * V
    possible = True

    for v in reversed(order):
        nonzero = []
        for to in graph[v]:
            if to != parent[v] and rem[to] != 0:
                nonzero.append(rem[to])

        if len(nonzero) > 2:
            possible = False
        elif len(nonzero) == 2:
            if nonzero[0] + nonzero[1] + 1 != K:
                possible = False

        rem[v] = (1 + sum(rem[to] for to in graph[v] if to != parent[v])) % K

    if possible and rem[0] == 0:
        print("Yes")
    else:
        print("No")

