    solve()

import sys


class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, value):
        while i <= self.n:
            self.bit[i] += value
            i += i & -i

    def sum(self, i):
        result = 0
        while i > 0:
            result += self.bit[i]
            i -= i & -i
        return result


def solve():
    input = sys.stdin.readline
    n = int(input())
    p = list(map(int, input().split()))

    fw = Fenwick(n)
    answer = 0

    for j, x in enumerate(p, 1):
        previous_greater = (j - 1) - fw.sum(x)
        answer += previous_greater * j - previous_greater * (previous_greater + 1) // 2
        fw.add(x, 1)

    print(answer)


