    solve()

import sys

def is_stable(s: str, x: int, y: int) -> bool:
    runs = []
    n = len(s)
    i = 0
    while i < n:
        j = i + 1
        while j < n and s[j] == s[i]:
            j += 1
        runs.append((s[i], j - i))
        i = j

    for (c1, l1), (c2, l2) in zip(runs, runs[1:]):
        if c1 == '0' and c2 == '1' and l1 >= x and l2 >= y:
            return False
        if c1 == '1' and c2 == '0' and l1 >= y and l2 >= x:
            return False
    return True

def ones_count_and_sum(s: str):
    count = 0
    pos_sum = 0
    for i, c in enumerate(s, 1):
        if c == '1':
            count += 1
            pos_sum += i
    return count, pos_sum

def main():
    input = sys.stdin.readline
    n, x, y = map(int, input().split())
    s = input().strip()
    t = input().strip()

    if s == t:
        print("Yes")
        return

    if is_stable(s, x, y) or is_stable(t, x, y):
        print("No")
        return

    cs, ss = ones_count_and_sum(s)
    ct, st = ones_count_and_sum(t)

    if cs != ct or (ss - st) % (x * y) != 0:
        print("No")
    else:
        print("Yes")

if __name__ == "__main__":
    main()

from typing import List


class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]

        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, idx))

        count = [0] * (n + 1)
        gain = [0] * len(conflictingPairs)

        max_a = 0
        second_a = 0
        max_id = -1
        base = 0

        for right in range(1, n + 1):
            for a, idx in buckets[right]:
                if a > max_a:
                    second_a = max_a
                    max_a = a
                    max_id = idx
                elif a < max_a and a > second_a:
                    second_a = a
                count[a] += 1

            base += right - max_a

            if max_a > 0 and count[max_a] == 1:
                gain[max_id] += max_a - second_a

        return base + max(gain, default=0)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        total = n + m - 1

        forced = [-1] * total
        for i, flag in enumerate(str1):
            if flag == 'T':
                for j, ch in enumerate(str2):
                    pos = i + j
                    value = ord(ch) - 97
                    if forced[pos] != -1 and forced[pos] != value:
                        return ""
                    forced[pos] = value

        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and str2[i] != str2[j]:
                j = pi[j - 1]
            if str2[i] == str2[j]:
                j += 1
            pi[i] = j

        transitions = [[0] * 26 for _ in range(m)]
        masks = [0] * m
        forbidden_masks = [0] * m
        last_char = ord(str2[-1]) - 97

        for state in range(m):
            mask = 0
            for c in range(26):
                k = state
                ch = chr(97 + c)
                while k > 0 and str2[k] != ch:
                    k = pi[k - 1]
                if str2[k] == ch:
                    k += 1
                if k == m:
                    k = pi[m - 1]
                transitions[state][c] = k
                mask |= 1 << k
            masks[state] = mask

            fm = 0
            for c in range(26):
                if state == m - 1 and c == last_char:
                    continue
                fm |= 1 << transitions[state][c]
            forbidden_masks[state] = fm

        all_states = (1 << m) - 1
        good = [0] * (total + 1)
        good[total] = all_states

        for pos in range(total - 1, -1, -1):
            nxt = good[pos + 1]
            current = 0
            is_forbidden_window = (
                pos >= m - 1 and str1[pos - m + 1] == 'F'
            )

            fixed = forced[pos]
            if fixed != -1:
                for state in range(m):
                    if is_forbidden_window and state == m - 1 and fixed == last_char:
                        continue
                    target = transitions[state][fixed]
                    if nxt & (1 << target):
                        current |= 1 << state
            else:
                possible_masks = forbidden_masks if is_forbidden_window else masks
                for state in range(m):
                    if possible_masks[state] & nxt:
                        current |= 1 << state

            good[pos] = current

        if not (good[0] & 1):
            return ""

        result = []
        state = 0

        for pos in range(total):
            fixed = forced[pos]
            if fixed != -1:
                candidates = [fixed]
            else:
                candidates = range(26)

            is_forbidden_window = (
                pos >= m - 1 and str1[pos - m + 1] == 'F'
            )

            for c in candidates:
                if is_forbidden_window and state == m - 1 and c == last_char:
                    continue

                target = transitions[state][c]
                if good[pos + 1] & (1 << target):
                    result.append(chr(97 + c))
                    state = target
                    break
            else:
                return ""

        return ''.join(result)

