MOD = 998244353

def compose(r, t):
    res = 0
    for src in (0, 1):
        row = 0
        for mid in (0, 1):
            if r & (1 << (2 * src + mid)):
                row |= (t >> (2 * mid)) & 3
        res |= row << (2 * src)
    return res

def build_options(transitions):
    opts = []
    for r in range(16):
        counts = {}
        for t in transitions:
            nr = compose(r, t)
            if nr:
                counts[nr] = counts.get(nr, 0) + 1
        opts.append(list(counts.items()))
    return opts

def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    s = data[1]

    # Transition relation masks, with bits indexed as:
    # (source, destination) -> 2 * source + destination
    unmarked = [
        1 << 1,                  # z = -1: 0 -> 1
        (1 << 0) | (1 << 3),     # z =  0: 0 -> 0, 1 -> 1
        1 << 2,                  # z =  1: 1 -> 0
    ]

    marked = [
        1 << 1,                                  # z = -1
        (1 << 0) | (1 << 1) | (1 << 3),          # z =  0
        (1 << 0) | (1 << 2) | (1 << 3),          # z =  1
        1 << 2,                                  # z =  2
    ]

    opts0 = build_options(unmarked)
    opts1 = build_options(marked)

    # Initially, either cyclic state may be the starting state.
    dp = [0] * 16
    dp[9] = 1  # identity relation: 0 -> 0 and 1 -> 1

    for bit in s:
        opts = opts1 if bit == ord('1') else opts0
        ndp = [0] * 16

        for state in range(16):
            value = dp[state]
            if value == 0:
                continue

            for nxt_state, multiplicity in opts[state]:
                if multiplicity == 1:
                    v = ndp[nxt_state] + value
                    if v >= MOD:
                        v -= MOD
                    ndp[nxt_state] = v
                else:
                    ndp[nxt_state] = (
                        ndp[nxt_state] + value * multiplicity
                    ) % MOD

        dp = ndp

    # A sequence is valid iff the final relation contains
    # a path from some state back to itself.
    answer = 0
    for state in range(16):
        if state & ((1 << 0) | (1 << 3)):
            answer += dp[state]
            if answer >= MOD:
                answer -= MOD

    print(answer)

if __name__ == "__main__":
    main()

