from array import array


def possible(k, src, dst):
    m = len(src)
    r = len(dst)

    left = array('i')
    right = array('i')

    lo = 0
    hi = 0
    for q in dst:
        while lo < m and src[lo] < q - k:
            lo += 1
        if hi < lo:
            hi = lo
        while hi < m and src[hi] <= q + k:
            hi += 1
        left.append(lo)
        right.append(hi)

    if left[0] != 0:
        return False

    gaps = [src[i] - src[i - 1] for i in range(1, m)]
    prev = 0
    ptr = 1

    for j in range(r - 1):
        if prev < left[j]:
            return False

        threshold = prev + 1
        if left[j + 1] > threshold:
            threshold = left[j + 1]

        if threshold > right[j]:
            return False

        if ptr < threshold:
            ptr = threshold

        need = dst[j + 1] - dst[j]
        while ptr <= right[j] and gaps[ptr - 1] < need:
            ptr += 1

        if ptr > right[j]:
            return False

        prev = ptr

    return prev >= left[-1] and prev < right[-1] and m <= right[-1]


