        dst = [i for i, c in enumerate(b) if c == '1']

        if len(src) < len(dst):
            answers.append("-1")
            continue

        if dst[-1] - dst[0] > src[-1] - src[0]:
            answers.append("-1")
            continue

        if not possible(n, src, dst):
            answers.append("-1")
            continue

        low = -1
        high = n

        while high - low > 1:
            mid = (low + high) // 2
            if possible(mid, src, dst):
                high = mid
            else:
                low = mid

        answers.append(str(high))

    sys.stdout.write("\n".join(answers))


