class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side
        positions = []

        for x, y in points:
            if y == 0:
                pos = x
            elif x == side:
                pos = side + y
            elif y == side:
                pos = 3 * side - x
            else:
                pos = 4 * side - y
            positions.append(pos)

        positions.sort()
        n = len(positions)
        extended = positions + [p + perimeter for p in positions]

        def feasible(distance: int) -> bool:
            for start in range(n):
                current = start
                start_pos = positions[start]

                for _ in range(k - 1):
                    next_index = bisect_left(
                        extended,
                        extended[current] + distance,
                        current + 1,
                    )
                    if next_index >= start + n:
                        break
                    current = next_index
                else:
                    if extended[current] <= start_pos + perimeter - distance:
                        return True

            return False

        low, high = 0, side + 1

        while high - low > 1:
            mid = (low + high) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid

        return low

