            if len(top) > 4:
                top.pop()

        if len(top) >= 3:
            branch[v] = 1 + sum(top[:3])

        # v is a leaf of the selected alkane, with one selected child.
        if max_branch_child != -1:
            answer = max(answer, 1 + max_branch_child)

        # v has degree 4 in the selected alkane, with four selected children.
