class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        total = n * m
        values = [x for row in grid for x in row]

        # Directions in clockwise order:
        # southeast, southwest, northwest, northeast
        directions = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # parity 0 means expected value 2, parity 1 means expected value 0
        straight = [
            [array("H", [0]) * total for _ in range(4)]
            for _ in range(2)
        ]
        turned = [
            [array("H", [0]) * total for _ in range(4)]
            for _ in range(2)
        ]

        for d, (dr, dc) in enumerate(directions):
            row_range = range(n - 1, -1, -1) if dr == 1 else range(n)

            for parity in range(2):
                expected = 2 if parity == 0 else 0
                next_parity = 1 - parity
                cur_straight = straight[parity][d]
                next_straight = straight[next_parity][d]

                for r in row_range:
                    nr = r + dr
                    row_base = r * m

                    for c in range(m):
                        idx = row_base + c
                        if values[idx] != expected:
                            continue

                        nc = c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            ni = nr * m + nc
                            cur_straight[idx] = 1 + next_straight[ni]
                        else:
                            cur_straight[idx] = 1

                cur_turned = turned[parity][d]
                next_turned = turned[next_parity][d]
                turn_dir = (d + 1) % 4
                next_turn_straight = straight[next_parity][turn_dir]

                for r in row_range:
                    nr = r + dr
                    row_base = r * m

                    for c in range(m):
                        idx = row_base + c
                        if values[idx] != expected:
                            continue

                        nc = c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            ni = nr * m + nc
                            best = next_turned[ni]
                            if next_turn_straight[ni] > best:
                                best = next_turn_straight[ni]
                            cur_turned[idx] = 1 + best
                        else:
                            cur_turned[idx] = 1

        answer = 1

        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue

                idx = r * m + c

                for d, (dr, dc) in enumerate(directions):
                    nr = r + dr
                    nc = c + dc

                    if 0 <= nr < n and 0 <= nc < m:
                        ni = nr * m + nc
                        length = 1 + turned[0][d][ni]
                        if length > answer:
                            answer = length

        return answer

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, b, c = p.split('*')

        def build_occurrences(pattern: str):
            m = len(pattern)
            occ = bytearray(n + 1)

            lps = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = lps[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                lps[i] = j

            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = lps[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    occ[i - m + 1] = 1
                    j = lps[j - 1]

            return occ

        def build_next_occurrence(pattern: str):
            occ = build_occurrences(pattern)
            sentinel = n + 1
            nxt = [sentinel] * (n + 1)
            last = sentinel

            for i in range(n, -1, -1):
                if occ[i]:
                    last = i
                nxt[i] = last

            return nxt

        la, lb, lc = len(a), len(b), len(c)

        occ_a = build_occurrences(a) if a else None
        next_b = build_next_occurrence(b) if b else None
        next_c = build_next_occurrence(c) if c else None

        sentinel = n + 1
        answer = sentinel

        max_start = n - la if la else n

        for start in range(max_start + 1):
            if la and not occ_a[start]:
                continue

            after_a = start + la

            if lb:
                if after_a > n:
                    continue
                start_b = next_b[after_a]
                if start_b == sentinel:
                    continue
            else:
                start_b = after_a

            after_b = start_b + lb

            if lc:
                if after_b > n:
                    continue
                start_c = next_c[after_b]
                if start_c == sentinel:
                    continue
            else:
                start_c = after_b

            length = start_c + lc - start
            if length < answer:
                answer = length

        return -1 if answer == sentinel else answer

