class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def feasible(target: int) -> bool:
            if target == 0:
                return True

            last_need = (target + points[-1] - 1) // points[-1]

            moves = 1
            current_visits = 1

            for i in range(n - 1):
                need = (target + points[i] - 1) // points[i]
                extra = max(0, need - current_visits)

                moves += 2 * extra
                if moves > m:
                    return False

                if i == n - 2:
                    # We may stop at index n-2 if the cycles already
                    # provided enough visits to the last index.
                    if extra >= last_need:
                        return moves <= m

                    moves += 1
                    last_visits = extra + 1
                    moves += 2 * (last_need - last_visits)
                    return moves <= m

                moves += 1
                current_visits = extra + 1

                if moves > m:
                    return False

            return True

        low, high = 0, min(points) * m

        while low < high:
            mid = (low + high + 1) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid - 1

        return low

