class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        limit = k + 1

        def contribution(is_min: bool) -> int:
            prev = [-1] * n
            nxt = [n] * n
            stack = []

            # Find the previous index that blocks ownership.
            for i, value in enumerate(nums):
                if is_min:
                    while stack and nums[stack[-1]] > value:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] < value:
                        stack.pop()

                if stack:
                    prev[i] = stack[-1]
                stack.append(i)

            stack.clear()

            # Find the next index that blocks ownership.
            for i in range(n - 1, -1, -1):
                value = nums[i]
                if is_min:
                    while stack and nums[stack[-1]] >= value:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] <= value:
                        stack.pop()

                if stack:
                    nxt[i] = stack[-1]
                stack.append(i)

            total = 0

            for i, value in enumerate(nums):
                left = i - prev[i]
                right = nxt[i] - i

                # Count pairs (x, y), where:
                # 1 <= x <= left, 1 <= y <= right, and x + y <= k + 1.
                q = min(left, limit - 1)
                p = min(q, max(0, limit - right))
                remaining = q - p

                count = (
                    p * right
                    + remaining * limit
                    - remaining * (p + 1 + q) // 2
                )
                total += value * count

            return total

        return contribution(True) + contribution(False)

import sys
import math

def solve():
    N, P = map(int, sys.stdin.readline().split())
    total_vertices = N - 1
    max_edges = N * (N - 1) // 2

    inv_fact = [1] * (N + 1)
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % P
    inv_fact[N] = pow(fact[N], P - 2, P)
    for i in range(N, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % P

    # Transition terms for consecutive layers of sizes a and b.
    # In the variable y = 1 + x, the factor is a sum of monomials.
    terms = [[None] * (N + 1) for _ in range(N + 1)]
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            cur = []
            base = b * (b - 1) // 2
            for j in range(b + 1):
                shift = base + a * (b - j)
                coef = math.comb(b, j) * inv_fact[b] % P
                if j & 1:
                    coef = (-coef) % P
                cur.append((shift, coef))
            terms[a][b] = cur

    # State: (number of non-root vertices used, number in odd layers, last layer size)
    # Value: polynomial in y, represented by its coefficient list.
    current = {(0, 0, 1): ([1], 0)}
    final_poly = [0] * (max_edges + 1)

    for layer_index in range(N - 1):
        nxt = {}

        for (used, odd_count, last_size), (poly, poly_max) in current.items():
            remaining = total_vertices - used
            for b in range(1, remaining + 1):
                new_used = used + b
                add_odd = b if layer_index % 2 == 0 else 0
                new_odd = odd_count + add_odd
                if new_odd > N // 2:
                    continue

                new_max = min(
                    max_edges,
                    poly_max + last_size * b + b * (b - 1) // 2
                )
                factor_terms = terms[last_size][b]

                # If this is a complete valid layering, accumulate directly.
                if new_used == total_vertices:
                    if new_odd != N // 2:
                        continue
                    for shift, coef in factor_terms:
                        limit = min(poly_max, max_edges - shift)
                        for k in range(limit + 1):
                            val = poly[k]
                            if val:
                                idx = k + shift
                                final_poly[idx] = (
                                    final_poly[idx] + val * coef
                                ) % P
                    continue

                key = (new_used, new_odd, b)
                if key not in nxt:
                    nxt[key] = ([0] * (new_max + 1), new_max)
                out, out_max = nxt[key]

                for shift, coef in factor_terms:
                    limit = min(poly_max, out_max - shift)
                    for k in range(limit + 1):
                        val = poly[k]
                        if val:
                            idx = k + shift
                            out[idx] = (out[idx] + val * coef) % P

        current = nxt
        if not current:
            break

    # Convert from y = 1 + x back to x, where x marks edges.
    answers = []
    label_factor = fact[N - 1]
    for m in range(N - 1, max_edges + 1):
        value = 0
        for k in range(m, max_edges + 1):
            if final_poly[k]:
                value = (value + final_poly[k] * math.comb(k, m)) % P
        answers.append(value * label_factor % P)

    print(*answers)

if __name__ == "__main__":
    solve()

import sys
import heapq
from array import array


def solve():
    input = sys.stdin.buffer.readline
    N, M = map(int, input().split())

    L = [0] * M
    R = [0] * M
    op1_by_l = [[] for _ in range(N + 2)]
    intervals = []

    for i in range(M):
        l, r = map(int, input().split())
        L[i] = l
        R[i] = r
        intervals.append((l, r, i))
        op1_by_l[l].append((r, i))

    # For every position p, determine the interval operation of type 1
    # reaching farthest among intervals with left endpoint <= p.
    reach = array('i', [0]) * (N + 2)
    best_id = array('i', [-1]) * (N + 2)

    cur_r = 0
    cur_id = -1
    for p in range(1, N + 1):
        for r, idx in op1_by_l[p]:
            if r > cur_r:
                cur_r = r
                cur_id = idx
        reach[p] = cur_r
        best_id[p] = cur_id

    reach[N + 1] = N + 1
    best_id[N + 1] = -1

    # Binary lifting for greedy interval covering.
    jump0 = array('i', [0]) * (N + 2)
    for p in range(1, N + 1):
        if reach[p] >= p:
            jump0[p] = reach[p] + 1
        else:
            jump0[p] = p
    jump0[N + 1] = N + 1

    LOG = (N + 2).bit_length()
    lifts = [jump0]
    for _ in range(1, LOG):
        prev = lifts[-1]
        cur = array('i', [0]) * (N + 2)
        for p in range(1, N + 2):
            cur[p] = prev[prev[p]]
        lifts.append(cur)

    INF = 10 ** 18

    def cover_count(a, b):
        if a > b:
            return 0
        if reach[a] < a:
            return INF

        p = a
        cnt = 0
        for k in range(LOG - 1, -1, -1):
            q = lifts[k][p]
            if q <= b:
                p = q
                cnt += 1 << k

        if reach[p] < p:
            return INF
        return cnt + 1

    # Reconstruct a greedy interval cover.
    def reconstruct_cover(a, b):
        ans = []
        p = a
        while p <= b:
            if reach[p] < p:
                return None
            ans.append(best_id[p])
            p = reach[p] + 1
        return ans

    best_cost = INF
    best_kind = None
    best_a = best_b = 0
    best_op2 = ()

    # No operation 2.
    c = cover_count(1, N)
    if c < best_cost:
        best_cost = c
        best_kind = 0
        best_a, best_b = 1, N
        best_op2 = ()

    # One operation 2.
    for i in range(M):
        c = cover_count(L[i], R[i])
        if c + 1 < best_cost:
            best_cost = c + 1
            best_kind = 1
            best_a, best_b = L[i], R[i]
            best_op2 = (i,)

    # Two operation 2's with disjoint intervals immediately cover everything.
    intervals_sorted = sorted(intervals)
    min_r = N + 1
    min_idx = -1
    disjoint_pair = None
    for l, r, idx in intervals_sorted:
        if min_r < l:
            disjoint_pair = (min_idx, idx)
            break
        if r < min_r:
            min_r = r
            min_idx = idx

    if disjoint_pair is not None and best_cost > 2:
        best_cost = 2
        best_kind = 2
        best_op2 = disjoint_pair
        best_a, best_b = 1, 0

    # For overlapping pairs, for each interval i choose the overlapping
    # interval j giving the smallest possible intersection endpoint.
    by_l = sorted(range(M), key=lambda i: L[i])
    heap = []
    pos = 0
    processed_min_r = N + 1

    while pos < M:
        current_l = L[by_l[pos]]
        group_end = pos
        while group_end < M and L[by_l[group_end]] == current_l:
            group_end += 1

        if processed_min_r < current_l:
            break

        for t in range(pos, group_end):
            i = by_l[t]
            heapq.heappush(heap, (R[i], i))

        while heap and heap[0][0] < current_l:
            heapq.heappop(heap)

        for t in range(pos, group_end):
            i = by_l[t]

            removed = []
            while heap and heap[0][1] == i:
                removed.append(heapq.heappop(heap))

            if heap:
                rj, j = heap[0]
                if rj <= R[i]:
                    a, b = current_l, rj
                    c = cover_count(a, b)
                    if c + 2 < best_cost:
                        best_cost = c + 2
                        best_kind = 2
                        best_a, best_b = a, b
                        best_op2 = (i, j)

            for item in removed:
                heapq.heappush(heap, item)

        for t in range(pos, group_end):
            i = by_l[t]
            if R[i] < processed_min_r:
                processed_min_r = R[i]

        pos = group_end

    if best_cost >= INF:
        print(-1)
        return

    cover = reconstruct_cover(best_a, best_b)
    if cover is None:
        print(-1)
        return

    ops = [0] * M
    for idx in best_op2:
        ops[idx] = 2

    used_op2 = set(best_op2)
    for idx in cover:
        if idx in used_op2:
            # This rare conflict can be avoided by leaving the operation
            # unused only when its type-1 interval is redundant.
            continue
        ops[idx] = 1

    # Verify the constructed solution. If a conflict occurred, rebuild
    # directly and reject only if the claimed optimum was not realizable.
    covered = bytearray(N + 1)
    for i, typ in enumerate(ops):
        if typ == 1:
            for p in range(L[i], R[i] + 1):
                covered[p] = 1
        elif typ == 2:
            for p in range(1, L[i]):
                covered[p] = 1
            for p in range(R[i] + 1, N + 1):
                covered[p] = 1

    if not all(covered[1:]):
        # Fallback: use the selected operation-2 intervals and all greedy
        # type-1 intervals, which is valid whenever the mathematical cover
        # exists.
        ops = [0] * M
        for idx in best_op2:
            ops[idx] = 2
        for idx in cover:
            if ops[idx] == 0:
                ops[idx] = 1

        covered = bytearray(N + 1)
        for i, typ in enumerate(ops):
            if typ == 1:
                for p in range(L[i], R[i] + 1):
                    covered[p] = 1
            elif typ == 2:
                for p in range(1, L[i]):
                    covered[p] = 1
                for p in range(R[i] + 1, N + 1):
                    covered[p] = 1

        if not all(covered[1:]):
            print(-1)
            return

    print(sum(1 for x in ops if x != 0))
    print(*ops)


if __name__ == "__main__":
    solve()

import sys


def mat_mul(a, b, mod):
    n = len(a)
    c = [[0] * n for _ in range(n)]
    for i in range(n):
        ci = c[i]
        ai = a[i]
        for k, x in enumerate(ai):
            if x:
                bk = b[k]
                for j in range(n):
                    ci[j] += x * bk[j]
        for j in range(n):
            ci[j] %= mod
    return c


def mat_pow(a, e, mod):
    n = len(a)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    while e:
        if e & 1:
            result = mat_mul(result, a, mod)
        a = mat_mul(a, a, mod)
        e >>= 1
    return result


def main():
    input = sys.stdin.readline
    n, p = map(int, input().split())
    a = [list(map(int, input().split())) for _ in range(n)]

    if p == 1:
        for _ in range(n):
            print(" ".join(["0"] * n))
        return

    zero_count = sum(row.count(0) for row in a)

    if p == 2:
        b = [[x if x else 1 for x in row] for row in a]
        ans = mat_mul(b, b, p)
        for row in ans:
            print(*row)
        return

    ans = mat_pow(a, p, p)

    sign = 1 if zero_count % 2 == 0 else p - 1
    for i in range(n):
        for j in range(n):
            ans[i][j] = ans[i][j] * sign % p

    # Contributions where exactly one zero entry is used p-1 times.
    # For p > 3, that zero entry must be a diagonal entry.
    for u in range(n):
        if a[u][u] != 0:
            continue

        for x in range(n):
            if x != u and a[x][u] != 0:
                ans[x][u] = (ans[x][u] + sign * a[x][u]) % p

        for y in range(n):
            if y != u and a[u][y] != 0:
                ans[u][y] = (ans[u][y] + sign * a[u][y]) % p

    # For p = 3, a non-diagonal zero edge may occur twice,
    # with the remaining edge being its reverse.
    if p == 3:
        for u in range(n):
            for v in range(n):
                if u != v and a[u][v] == 0 and a[v][u] != 0:
                    ans[u][v] = (ans[u][v] + sign * a[v][u]) % p

    for row in ans:
        print(*row)


if __name__ == "__main__":
    main()

import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M, A, B = data[:4]
    intervals = []
    idx = 4
    for _ in range(M):
        L, R = data[idx], data[idx + 1]
        idx += 2
        intervals.append((L, R))

    if A == B:
        if (N - 1) % A != 0:
            print("No")
            return

        for L, R in intervals:
            first = L + (1 - L) % A
            if first <= R:
                print("No")
                return

        print("Yes")
        return

    full = (1 << B) - 1
    allowed = full ^ ((1 << (A - 1)) - 1)

    current = 1
    mask = 1  # bit k represents reachability of current - k

    def advance_clear(end):
        nonlocal current, mask

        while current < end and mask != 0 and mask != full:
            reachable = 1 if (mask & allowed) else 0
            mask = ((mask << 1) & full) | reachable
            current += 1

        if current < end:
            current = end
            if mask == 0:
                mask = 0
            else:
                mask = full

    for L, R in intervals:
        advance_clear(L - 1)

        length = R - L + 1
        if length >= B:
            current = R
            mask = 0
        else:
            for _ in range(length):
                mask = (mask << 1) & full
                current += 1

    advance_clear(N)
    print("Yes" if (mask & 1) else "No")


if __name__ == "__main__":
    solve()

from typing import List
from bisect import bisect_left


class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        items = sorted(
            (l, r, w, idx)
            for idx, (l, r, w) in enumerate(intervals)
        )
        ends = [item[1] for item in items]

        neg_inf = -1
        scores = [[neg_inf] * 5 for _ in range(n + 1)]
        choices = [[None] * 5 for _ in range(n + 1)]

        scores[0][0] = 0
        choices[0][0] = ()

        for i, (left, right, weight, index) in enumerate(items, 1):
            scores[i] = scores[i - 1].copy()
            choices[i] = choices[i - 1].copy()

            previous = bisect_left(ends, left, 0, i - 1)

            for count in range(1, 5):
                if scores[previous][count - 1] == neg_inf:
                    continue

                base = choices[previous][count - 1]
                pos = bisect_left(base, index)
                candidate_choice = base[:pos] + (index,) + base[pos:]
                candidate_score = scores[previous][count - 1] + weight

                current_score = scores[i][count]
                current_choice = choices[i][count]

                if (
                    candidate_score > current_score
                    or (
                        candidate_score == current_score
                        and (
                            current_choice is None
                            or candidate_choice < current_choice
                        )
                    )
                ):
                    scores[i][count] = candidate_score
                    choices[i][count] = candidate_choice

        best_score = neg_inf
        best_choice = ()

        for count in range(5):
            if (
                scores[n][count] > best_score
                or (
                    scores[n][count] == best_score
                    and choices[n][count] < best_choice
                )
            ):
                best_score = scores[n][count]
                best_choice = choices[n][count]

        return list(best_choice)

