import sys


def cross(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])


def main():
    input = sys.stdin.readline
    n = int(input())
    points = [tuple(map(int, input().split())) for _ in range(n)]

    lower = []
    upper = []

    best_num = None
    best_den = 1

    for x, h in points:
        def value(p):
            px, ph = p
            return x * ph - px * h, x - px

        def greater(a, b):
            na, da = value(a)
            nb, db = value(b)
            return na * db > nb * da

        def query(hull):
            m = len(hull)
            if m == 0:
                return None

            left, right = 0, m - 1
            while left < right:
                mid = (left + right) // 2
                if greater(hull[mid + 1], hull[mid]):
                    left = mid + 1
                else:
                    right = mid

            candidates = {0, m - 1, left}
            result = None
            for idx in candidates:
                p = hull[idx]
                if result is None or greater(p, result):
                    result = p
            return result

        for hull in (lower, upper):
            p = query(hull)
            if p is not None:
                num, den = value(p)
                if best_num is None or num * best_den > best_num * den:
                    best_num = num
                    best_den = den

        point = (x, h)

        while len(lower) >= 2 and cross(lower[-2], lower[-1], point) <= 0:
            lower.pop()
        lower.append(point)

        while len(upper) >= 2 and cross(upper[-2], upper[-1], point) >= 0:
            upper.pop()
        upper.append(point)

    if best_num is None or best_num < 0:
        print(-1)
    else:
        print("{:.15f}".format(best_num / best_den))


if __name__ == "__main__":
    main()

import sys
from bisect import bisect_right

def solve():
    data = sys.stdin.buffer.read().split()
    it = iter(data)

    n = int(next(it))
    m = int(next(it))
    x = int(next(it))
    y = int(next(it))

    houses = [(int(next(it)), int(next(it))) for _ in range(n)]

    horizontal = {}
    vertical = {}

    for _ in range(m):
        d = next(it)
        c = int(next(it))

        if d == b'U':
            vertical.setdefault(x, []).append((y, y + c))
            y += c
        elif d == b'D':
            vertical.setdefault(x, []).append((y - c, y))
            y -= c
        elif d == b'L':
            horizontal.setdefault(y, []).append((x - c, x))
            x -= c
        else:  # R
            horizontal.setdefault(y, []).append((x, x + c))
            x += c

    def merge_intervals(groups):
        for key, intervals in groups.items():
            intervals.sort()
            starts = []
            ends = []

            for left, right in intervals:
                if starts and left <= ends[-1]:
                    if right > ends[-1]:
                        ends[-1] = right
                else:
                    starts.append(left)
                    ends.append(right)

            groups[key] = (starts, ends)

    merge_intervals(horizontal)
    merge_intervals(vertical)

    count = 0

    for hx, hy in houses:
        visited = False

        intervals = horizontal.get(hy)
        if intervals is not None:
            starts, ends = intervals
            idx = bisect_right(starts, hx) - 1
            if idx >= 0 and hx <= ends[idx]:
                visited = True

        if not visited:
            intervals = vertical.get(hx)
            if intervals is not None:
                starts, ends = intervals
                idx = bisect_right(starts, hy) - 1
                if idx >= 0 and hy <= ends[idx]:
                    visited = True

        if visited:
            count += 1

    print(x, y, count)

if __name__ == "__main__":
    solve()

