def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    H, W, X = data[0], data[1], data[2]
    P, Q = data[3] - 1, data[4] - 1
    values = data[5:]

    start = P * W + Q
    strength = values[start]
    visited = bytearray(H * W)
    visited[start] = 1

    heap = []

    def add(r, c):
        idx = r * W + c
        if not visited[idx]:
            visited[idx] = 1
            heapq.heappush(heap, (values[idx], idx))

    if P > 0:
        add(P - 1, Q)
    if P + 1 < H:
        add(P + 1, Q)
    if Q > 0:
        add(P, Q - 1)
    if Q + 1 < W:
        add(P, Q + 1)

    while heap and heap[0][0] * X < strength:
        value, idx = heapq.heappop(heap)
        strength += value

        r, c = divmod(idx, W)
        if r > 0:
            add(r - 1, c)
        if r + 1 < H:
            add(r + 1, c)
        if c > 0:
            add(r, c - 1)
        if c + 1 < W:
            add(r, c + 1)

    print(strength)

